CREATE TABLE IF NOT EXISTS officers(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER NOT NULL REFERENCES members(id),unit_id TEXT NOT NULL REFERENCES units(id),position TEXT NOT NULL,term_start TEXT NOT NULL,term_end TEXT NOT NULL,card_token TEXT NOT NULL UNIQUE,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(term_start<=term_end)); CREATE UNIQUE INDEX IF NOT EXISTS officer_current ON officers(member_id) WHERE revoked_at IS NULL; CREATE INDEX IF NOT EXISTS officer_unit ON officers(unit_id);